package com.javacodingagent.bootstrap.security;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig { @Bean JwtService jwtService(@Value("${coding-agent.security.jwt-secret:}") String secret) { return new JwtService(secret); } @Bean SecurityFilterChain security(HttpSecurity http, JwtService jwt) throws Exception { return http.csrf(c -> c.disable()).sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a -> a.requestMatchers("/api/health", "/api/auth/token", "/actuator/health", "/v3/api-docs/**", "/swagger-ui/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtAuthenticationFilter(jwt), UsernamePasswordAuthenticationFilter.class).build(); } }
